begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.payload(n integer) returns jsonb language sql as $$select jsonb_build_object('version',1,'transactionId',pg_temp.i(n),'organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'deviceId',pg_temp.i(501),'cashierId',auth.uid(),'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and device_id=pg_temp.i(501) and closed_at is null),'occurredAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',75000,'cashReceived',100000,'items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301),'unitId',pg_temp.i(401),'batchId',null,'name','Grower feeds','unitName','Sack','quantity','0.5','factor','50','unitPrice',150000,'unitCost',120000,'priceVersion',1,'lineTotal',75000)))$$;

create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.transfer_receipt(q text default '30') returns jsonb language sql as $$select pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity',q,'heldQuantity','10','reason','TEST physical count: 30 saleable, 10 damaged, 10 missing')$$;
create function pg_temp.stock(b integer default 101) returns text language sql as $$select quantity::text from public.branch_inventory where branch_id=pg_temp.i(b) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.plan(saleid integer default 701) returns jsonb language sql as $$select public.agri_command('partial_refund_plan',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid)))$$;
create function pg_temp.refund(ident integer,q text default '0.2',t text default '0',d text default 'not_returned',saleid integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(ident),'shiftId',(select id from public.cashier_shifts where closed_at is null and branch_id=pg_temp.i(101)),'reference','TEST signed partial refund','reason','TEST inspected physical return and original cash amount','physicalConfirmed',true,'expectedRefundVersion',pg_temp.plan(saleid)->'version','expectedAmount',round((pg_temp.plan(saleid)->'lines'->0->>'lineTotal')::numeric*((pg_temp.plan(saleid)->'lines'->0->>'refundedQuantity')::numeric+q::numeric)/(pg_temp.plan(saleid)->'lines'->0->>'quantity')::numeric)::bigint-(pg_temp.plan(saleid)->'lines'->0->>'refundedAmount')::bigint,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity',q,'returnedQuantity',t,'disposition',d)))$$;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;

create function pg_temp.check_refund(ident integer,kind text default 'partial',saleid integer default 701) returns jsonb language sql as $$select public.agri_command('refund_correction_check',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(ident),'refundKind',kind,'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and branch_id=pg_temp.i(101) and closed_at is null)))$$;
create function pg_temp.correction(ident integer,refundid integer,kind text default 'partial',saleid integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(refundid),'refundKind',kind,'correctionId',pg_temp.i(ident),'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and branch_id=pg_temp.i(101) and closed_at is null),'expectedLedgerRevision',pg_temp.check_refund(refundid,kind,saleid)->>'ledgerRevision','expectedRefundVersion',pg_temp.check_refund(refundid,kind,saleid)->'refundVersion','cashRestoredCentavos',pg_temp.check_refund(refundid,kind,saleid)->'cashToRestore','reference','TEST signed refund correction','reason','TEST mistaken refund; full cash and actual goods checked','cashConfirmed',true,'goodsConfirmed',true,'queuesConfirmed',true)$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',10000));
select public.agri_command('record_sale',pg_temp.payload(701));
select public.agri_command('partial_refund_sale',(select data from saved where name='refund'));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'shiftId',(select id from public.cashier_shifts where closed_at is null),'countedCash',70000));
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',0));
select public.agri_command('correct_refund',(select data from saved where name='secondCorrection'));
-- Full refund with complete physical evidence may be corrected, then uses selected quantities.
select public.agri_command('record_sale',pg_temp.payload(702));
select public.agri_command('refund_sale',(select data from saved where name='full'));
select public.agri_command('correct_refund',pg_temp.correction(903,804,'full',702));
-- Subsequent real stock activity makes automatic removal unsafe even if balance is restored.
select public.agri_command('record_sale',pg_temp.payload(703));
select public.agri_command('partial_refund_sale',pg_temp.refund(806,'0.1','0.1','resalable',703));
select public.agri_command('record_sale',pg_temp.payload(704));
-- Held-only return has no saleable stock credit, but disposing held goods blocks undo.
select public.agri_command('partial_refund_sale',pg_temp.refund(807,'0.1','0.1','hold',704));
select public.agri_command('disposition_hold',pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(807)),'dispositionId',pg_temp.i(905),'quantity','1','disposition','dispose','reason','TEST documented damaged returned goods'));
-- Later active financial portions must be corrected newest first.
select public.agri_command('record_sale',pg_temp.payload(705));
select public.agri_command('partial_refund_sale',pg_temp.refund(808,'0.1','0','not_returned',705));
select public.agri_command('partial_refund_sale',pg_temp.refund(809,'0.1','0','not_returned',705));
select public.agri_command('correct_refund',pg_temp.correction(906,809,'partial',705));
-- A zero-change physical count still seals the return stock; owner cannot erase that evidence.
select public.agri_command('record_sale',pg_temp.payload(706));
select public.agri_command('partial_refund_sale',pg_temp.refund(811,'0.1','0.1','resalable',706));
reset role;
set local role authenticated;select pg_temp.login(11);
-- Financial allocation after undo still assigns every original centavo exactly once.
select public.agri_command('set_price',pg_temp.ctx()||jsonb_build_object('unitId',pg_temp.i(401),'price',333,'cost',100,'reason','TEST correction centavo fixture'));
select public.agri_command('record_sale',pg_temp.payload(707)||jsonb_build_object('total',100,'cashReceived',100,'items',jsonb_build_array((pg_temp.payload(707)->'items'->0)||'{"quantity":"0.3","unitPrice":333,"unitCost":100,"priceVersion":2,"lineTotal":100}')));
select public.agri_command('partial_refund_sale',pg_temp.refund(812,'0.1','0','not_returned',707));
select public.agri_command('partial_refund_sale',pg_temp.refund(813,'0.1','0','not_returned',707));
select public.agri_command('partial_refund_sale',pg_temp.refund(814,'0.1','0','not_returned',707));
select public.agri_command('correct_refund',pg_temp.correction(907,814,'partial',707));
select public.agri_command('correct_refund',pg_temp.correction(908,813,'partial',707));
select public.agri_command('partial_refund_sale',pg_temp.refund(815,'0.1','0','not_returned',707));
select public.agri_command('partial_refund_sale',pg_temp.refund(816,'0.1','0','not_returned',707));
-- Legacy full refund with no physical source event must stay retained.
reset role;
set local role authenticated;select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;
update auth.sessions set not_after=now()-interval '1 second' where user_id=pg_temp.i(11);
set local role authenticated;select pg_temp.login(11);
reset role;
select line from tap_results;
select * from finish();
rollback;
